import{_ as a,o as e,c as s,a5 as d}from"./chunks/framework.DGp912Ge.js";const k=JSON.parse('{"title":"High Level Command — 빠른 시작","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/guides/sdk-cpp/high-level.md","filePath":"ko/guides/sdk-cpp/high-level.md","lastUpdated":1785209402000}'),i={name:"ko/guides/sdk-cpp/high-level.md"};function n(h,t,l,o,p,r){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="high-level-command-—-빠른-시작" tabindex="-1">High Level Command — 빠른 시작 <a class="header-anchor" href="#high-level-command-—-빠른-시작" aria-label="Permalink to &quot;High Level Command — 빠른 시작&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_high_level.cpp</code></p><p><code>HighLevelCommand</code>를 50 Hz로 발행합니다. 터미널에서 보행을 선택하고, 조이스틱으로 속도를 제어합니다.</p><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/cpp/example</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">networkInterfac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [joystickPath]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./bin/rbq_high_level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span></code></pre></div><p>조이스틱이 필요합니다. <code>/dev/input/js*</code>에서 자동으로 감지됩니다 (Logitech/Xbox 이름 우선).<br> 경로를 직접 지정하려면: <code>./bin/rbq_high_level eth0 /dev/input/js1</code></p><h2 id="터미널-사용법" tabindex="-1">터미널 사용법 <a class="header-anchor" href="#터미널-사용법" aria-label="Permalink to &quot;터미널 사용법&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list            ← 예제 내장 목록 출력</span></span>
<span class="line"><span>standing        ← 이름으로 전환</span></span>
<span class="line"><span>3               ← ID로 전환 (trotting)</span></span>
<span class="line"><span>waving          ← 웨이브 보행 전환</span></span></code></pre></div><h2 id="지원-보행-목록" tabindex="-1">지원 보행 목록 <a class="header-anchor" href="#지원-보행-목록" aria-label="Permalink to &quot;지원 보행 목록&quot;">​</a></h2><table tabindex="0"><thead><tr><th>이름</th><th>ID</th><th>설명</th></tr></thead><tbody><tr><td><code>sitting</code></td><td>0</td><td>앉기</td></tr><tr><td><code>standing</code></td><td>1</td><td>서기 (시작 기본값)</td></tr><tr><td><code>trotting</code></td><td>3</td><td>MPC 트롯</td></tr><tr><td><code>trot_stairs</code></td><td>4</td><td>계단 오르기 트롯</td></tr><tr><td><code>waving</code></td><td>5</td><td>웨이브 보행</td></tr><tr><td><code>docking</code></td><td>10</td><td>자동 도킹</td></tr></tbody></table><blockquote><p>예제 내장 목록에는 지원하지 않는 내부 보행도 함께 출력됩니다. 위 표의 보행만 사용하세요.</p></blockquote><h2 id="조이스틱-속도" tabindex="-1">조이스틱 속도 <a class="header-anchor" href="#조이스틱-속도" aria-label="Permalink to &quot;조이스틱 속도&quot;">​</a></h2><table tabindex="0"><thead><tr><th>축</th><th>명령</th><th>최대값</th></tr></thead><tbody><tr><td>L 스틱 앞/뒤</td><td><code>vel_x</code></td><td>±1.2 m/s</td></tr><tr><td>L 스틱 좌/우</td><td><code>vel_y</code></td><td>±0.5 m/s</td></tr><tr><td>R 스틱 좌/우</td><td><code>omega_z</code></td><td>±60 deg/s</td></tr></tbody></table><blockquote><p><code>omega_z</code>는 <strong>deg/s</strong> 단위입니다. QuadWalk가 내부에서 rad/s로 변환합니다.</p></blockquote><h2 id="중요" tabindex="-1">중요 <a class="header-anchor" href="#중요" aria-label="Permalink to &quot;중요&quot;">​</a></h2><p>시작 시 <code>switchControlMode = true</code>를 자동으로 발행합니다.<br> 이 토픽이 없으면 로봇은 <code>HighLevelCommand</code>를 무시하고 조이스틱 모드를 유지합니다.</p><p>조이스틱 자동 감지는 Sport Client (조이스틱) 예제와 동일한 로직으로 동작합니다.</p><p>→ <strong>전체 레퍼런스</strong>: <a href="/RBQ/ko/software/sdk/cpp/high-level.html">High Level Command</a></p>`,20)])])}const g=a(i,[["render",n]]);export{k as __pageData,g as default};
